void EmptyTheList(List * plist)
{
Node * psave;
while (*plist != NULL)
{
psave = (*plist)->next;      /* 保存下一个节点的地址   */
free(*plist);                  /* 释放当前节点          */
*plist = psave;              /* 前进至下一个节点     */
}
}
/* 局部函数定义 */
